extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var q_easy := Question.new("Facile?", ["Vero", "Falso"], 0)
	var q_diff1 := Question.new("Difficile 1?", ["A", "B", "C", "D"], 1)
	var q_diff2 := Question.new("Difficile 2?", ["X", "Y", "Z"], 2)
	var all_questions: Array[Question] = [q_easy, q_diff1, q_diff2]

	var diff_result: Array = call_if_exists(QuizData, "filter_difficult_questions", [all_questions], [])
	if not check("filter_diff_count", diff_result.size() == 2, "filter_difficult_questions deve restituire solo le 2 domande con più di 2 opzioni (ha restituito %d)" % diff_result.size()):
		return

	check("filter_diff_content", diff_result.has(q_diff1) and diff_result.has(q_diff2), "Le domande difficili restituite devono essere q_diff1 e q_diff2")

	var wrong_pool: Array[Question] = [q_diff1]
	var wrong_result: Array = call_if_exists(QuizData, "filter_wrong_questions", [all_questions, wrong_pool], [])
	if not check("filter_wrong_count", wrong_result.size() == 1, "filter_wrong_questions deve restituire solo 1 domanda (ha restituito %d)" % wrong_result.size()):
		return

	check("filter_wrong_content", wrong_result[0] == q_diff1, "La domanda sbagliata restituita deve essere q_diff1")

	var session := QuizSession.new([q_easy, q_diff1])
	session.submit_answer(1)
	var recorded_wrong: Array = call_if_exists(session, "get_wrong_questions", [], [])
	check("session_wrong_count", recorded_wrong.size() == 1 and recorded_wrong.has(q_easy), "QuizSession deve registrare q_easy tra le domande sbagliate dopo una risposta errata")

